    if resp and isinstance(resp, list):
        threads=resp
    elif resp and isinstance(resp, dict):
        threads = resp.get('threads') or resp.get('data') or resp.get('results')
    if threads is None:
        # try direct resp structure
        print('unexpected show_inbox_threads response keys', resp.keys())
        threads=[]
    print('page', page_index, 'n', len(threads))
    if not threads:
        break
    all_threads.extend(threads)
    page_index += 1
    if page_index>10:
        break
print('total threads', len(all_threads))
# print top 5 candidates summary
for t in all_threads[:5]:
    print('thread_id', t.get('email_thread_id') or t.get('thread_id'), 'subject', t.get('subject'), 'from', (t.get('participants',[{}])[0] if t.get('participants') else None))

